WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_solution_single'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '单一对策题', 'kp-sl-solution-single', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "提出对策：单一对策题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "直接给问题开药方。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、答题骨架"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "绝不是只写干巴巴的一句话。对策必须有血有肉！"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{完整对策} = \\text{主语} + \\text{动词} + \\text{宾语} + \\text{目的/效果}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "例如：“【政府环保部门】应【加大】【执法力度】，【以有效遏制企业偷排乱放现象】。”"}]}]}$$ AS jsonb), NULL, '单一对策题的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "提出对策", "单一对策"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_solution_single", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
